select '' as field, '' as message, 'on$&Identity;Filter$Retrieve$QueryComplete(this, ''&Identity;'', [''' + @xloai_vv + ''', ''' + @nh_vv1 + ''', ''' + @nh_vv2 + ''', ''' + @nh_vv3 + ''', ''' + @nh_vv4 + ''', ''' + @ma_dvcs + ''']);' as script
return








function init$&Identity;Filter$(f) {}
function active$&Identity;Filter$(f) {
	var g = f.grid, w = g.get_element().parentForm;
	f.setItemValue('ma_dvcs', w.getItemValue('ma_dvcs1'));
	changeLookupReadonly(f, 'nh_vv1');
	changeLookupReadonly(f, 'nh_vv2');
	changeLookupReadonly(f, 'nh_vv3');
	changeLookupReadonly(f, 'nh_vv4');
	changeLookupReadonly(f, 'ma_dvcs');
}
function close$&Identity;Filter$(f) {}
function on$&Identity;Filter$Retrieve$QueryComplete(f, h, l) {
	var g = f.grid;
	g._filter$Fields = l;
	set$&Identity;Filter$FormScript(g, h);
}
function set$&Identity;Filter$FormScript(g, h) {g._formScript = 'show$&Identity;Filter$QueryComplete(this,\'' + (h ? h : '') + '\')';}
function show$&Identity;Filter$QueryComplete(g, h) {
	g.showForm(h);
	g._memvars = [];
}

function changeLookupReadonly(f, c) {
	var o = f.getItem(c);
	f._setReadOnly(o, false);
	if ($func.isIF) o.readOnly = false; else {
		try {
			$removeHandler(o, 'keydown', f._readOnlyKeyHandler);
			if ($func.isOpr) $removeHandler(o, 'keypress', f._readOnlyKeyHandler);
			o.AddReadOnlyKeyHandler = null;
		} catch (ex) {}
	}
}




